package org.stackdocs.app;

import android.app.AlertDialog;
import android.os.Bundle;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;

/** Destructive actions stay local and require separate warnings plus a phrase. */
public final class LibraryResetActivity extends LibraryActivity {
    private Runnable removeBack;
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=Ui.column(this);LinearLayout bar=Ui.toolbar(this);bar.addView(Ui.iconButton(this,Icons.Symbol.BACK,"Back",this::finish));bar.addView(Ui.text(this,"Reset or rebuild library",18,false));root.addView(bar);ScrollView scroll=new ScrollView(this);LinearLayout body=Ui.column(this);int p=Ui.dp(this,24);body.setPadding(p,p,p,p);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        body.addView(Ui.text(this,"Only this phone",22,false));body.addView(Ui.text(this,"Reset never erases your computer remotely. Keep a checked backup or a complete copy on another device before continuing.",16,false));
        android.widget.TextView counts=Ui.text(this,"Checking library…",16,false);body.addView(counts);
        body.addView(Ui.actionRow(this,Icons.Symbol.TUNE,"Start a new connection","Keep documents; discard the old sync connection",0xFFF7E1A3,()->warnConnection()));body.addView(Ui.divider(this));
        body.addView(Ui.actionRow(this,Icons.Symbol.DOCUMENTS,"Erase this phone's library","Remove documents, unfinished scans and local sync history",0xFFF0E3EF,()->warnErase()));
        body.addView(Ui.text(this,"After erasing, reopen Stack and choose Restore library or Set up a computer. To resync from the computer, start a new connection there while keeping its documents. Never erase both copies unless you have a separate backup.",16,false));
        Ui.install(this,root);removeBack=Ui.backHandler(this,this::finish);
        work(()->{android.database.sqlite.SQLiteDatabase db=app().library.database();try(android.database.Cursor c=db.rawQuery("SELECT (SELECT count(*) FROM documents),(SELECT count(*) FROM pages),(SELECT count(*) FROM stacks)",null)){c.moveToFirst();return c.getLong(0)+" documents · "+c.getLong(1)+" pages · "+c.getLong(2)+" stacks";}},counts::setText);
    }
    @Override protected void onDestroy(){if(removeBack!=null)removeBack.run();super.onDestroy();}
    private boolean canReset(){if(app().archives.busy()||app().archives.state.equals("review")||app().imports.busy||app().batches.busy()){new AlertDialog.Builder(this).setTitle("Finish current operations first").setMessage("Finish or cancel backup, restore, import and batch operations before reviewing a reset. Check that your recovery backup opens before erasing.").setPositiveButton("OK",null).show();return false;}return true;}
    private void warnErase(){if(!canReset())return;new AlertDialog.Builder(this).setTitle("1 of 3 — Erase this phone's library?").setMessage("This removes all local saved documents and originals, page edits, details, recognized text, unfinished scans and sync history. Your computer and backup files saved elsewhere are kept.\n\nDeleted local data cannot be recovered without a separate copy.").setNegativeButton("Keep my library",null).setPositiveButton("Review recovery warning",(d,w)->new AlertDialog.Builder(this).setTitle("2 of 3 — Check your recovery copy").setMessage("Make and check a backup first, or make sure your computer contains everything you need. Unsynced phone changes will be lost.\n\nDo not erase both devices unless you have an independent backup. Sync cannot recover the only copy after both libraries are erased.\n\nStack will close. Reopen it to complete the reset, then restore a backup or set up a new connection. Automatic photo import will be turned off.").setNegativeButton("Cancel",null).setPositiveButton("Continue to final confirmation",(x,y)->confirm(LibraryReset.ERASE)).show()).show();}
    private void warnConnection(){if(!canReset())return;new AlertDialog.Builder(this).setTitle("Start a new connection?").setMessage("Your saved documents and unfinished scans stay on this phone. The old sync history, confirmations and computer enrollment are forgotten; this phone gets a fresh sync identity.\n\nThe other device must also choose Start a new connection while keeping its documents. Then pair again and review document matches. This does not erase or change the other device.\n\nStack will close; reopen it to finish.").setNegativeButton("Keep current connection",null).setPositiveButton("Continue",(d,w)->confirm(LibraryReset.CONNECTION)).show();}
    private void confirm(String mode){boolean erase=mode.equals(LibraryReset.ERASE);String phrase=erase?"ERASE THIS PHONE":"RESET CONNECTION";EditText field=new EditText(this);field.setSingleLine();field.setHint(phrase);field.setContentDescription("Confirmation phrase");field.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(erase?"3 of 3 — Final erase confirmation":"Confirm new connection").setMessage("Type "+phrase+" exactly.\n\n"+(erase?"All documents in this phone's local library will be removed after you reopen Stack.":"Your local sync connection will be forgotten; saved documents are kept.")).setView(field).setNegativeButton("Cancel",null).setPositiveButton(erase?"Erase library and close Stack":"Reset connection and close Stack",null).create();
        dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(!canReset())return;if(!field.getText().toString().equals(phrase)){field.setError("Type the complete phrase exactly.");return;}dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);whenAllowed(()->work(()->{if(app().archives.busy()||app().archives.state.equals("review")||app().imports.busy||app().batches.busy())throw new java.io.IOException("Finish active backup, import or batch work first.");new LibraryReset(this).schedule(mode);return true;},ok->{app().resetRequested=true;dialog.dismiss();finishAffinity();android.os.Process.killProcess(android.os.Process.myPid());},()->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true)));}));dialog.show();
    }
}
